  public static string Root=>Path.Combine(Path.GetDirectoryName(typeof(SanguoshaView).Assembly.Location),"Sanguosha");static readonly Dictionary<string,Texture2D> images=new Dictionary<string,Texture2D>();static readonly Dictionary<string,Sprite> sprites=new Dictionary<string,Sprite>();
  public static Texture2D Image(string path){if(images.TryGetValue(path,out var t)&&t!=null)return t;string f=Path.Combine(Root,path);if(!File.Exists(f))return null;t=new Texture2D(2,2,TextureFormat.RGBA32,false);ImageConversion.LoadImage(t,File.ReadAllBytes(f));t.filterMode=FilterMode.Bilinear;t.wrapMode=TextureWrapMode.Clamp;images[path]=t;return t;}
  public static Sprite Sprite(string id){if(sprites.TryGetValue(id,out var s)&&s!=null)return s;var t=Image(id=="box"?"back.png":"generals/"+id+".jpg");if(t==null)return null;s=UnityEngine.Sprite.Create(t,new Rect(0,0,t.width,t.height),new Vector2(.5f,.5f),100);sprites[id]=s;return s;}
