  IEnumerator LoadSounds(){string dir=Path.Combine(SanguoshaAssets.Root,"audio");if(!Directory.Exists(dir))yield break;var files=Directory.GetFiles(dir,"*.ogg").OrderBy(f=>Path.GetFileNameWithoutExtension(f)=="background"?0:1);foreach(var f in files){using(var request=UnityWebRequestMultimedia.GetAudioClip(new Uri(f).AbsoluteUri,AudioFormat(f))){yield return request.SendWebRequest();if(Closed)yield break;if(request.result!=UnityWebRequest.Result.Success)continue;string key=Path.GetFileNameWithoutExtension(f);clips[key]=DownloadHandlerAudioClip.GetContent(request);if(key=="background"){music.clip=clips[key];if(!Paused)music.Play();}}}}
  static AudioType AudioFormat(string path){using(var f=File.OpenRead(path)){byte[] head=new byte[4];f.Read(head,0,4);return head[0]==82&&head[1]==73&&head[2]==70&&head[3]==70?AudioType.WAV:head[0]==79&&head[1]==103&&head[2]==103&&head[3]==83?AudioType.OGGVORBIS:AudioType.MPEG;}}
